import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"飞书（Lark）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/feishu.md","filePath":"zh/integrations/channels/feishu.md","lastUpdated":1790952322000}'),n={name:"zh/integrations/channels/feishu.md"};function s(l,t,i,h,d,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="飞书-lark" tabindex="-1">飞书（Lark） <a class="header-anchor" href="#飞书-lark" aria-label="Permalink to &quot;飞书（Lark）&quot;">​</a></h1><p>通过飞书开放平台接入，让企业 Bot 在群聊和私聊里与用户交互。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一个能登录 <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">飞书开放平台</a>、可创建企业自建应用的账号。</li><li>一个 Memoh Bot；渠道在它的 <strong>平台</strong> 标签页里配置。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在飞书开放平台创建自建应用" tabindex="-1">1. 在飞书开放平台创建自建应用 <a class="header-anchor" href="#_1-在飞书开放平台创建自建应用" aria-label="Permalink to &quot;1. 在飞书开放平台创建自建应用&quot;">​</a></h3><ol><li>打开 <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">飞书开放平台</a> 并登录。</li><li>点 <strong>创建企业自建应用</strong>，填名称与简介后创建。</li><li>左侧进入 <strong>凭证与基础信息</strong>。</li><li>复制 <strong>App ID</strong> 和 <strong>App Secret</strong>。</li></ol><h3 id="_2-在飞书开放平台启用-bot-能力" tabindex="-1">2. 在飞书开放平台启用 Bot 能力 <a class="header-anchor" href="#_2-在飞书开放平台启用-bot-能力" aria-label="Permalink to &quot;2. 在飞书开放平台启用 Bot 能力&quot;">​</a></h3><p>进入 <strong>应用能力</strong> → <strong>Bot</strong>，点启用。</p><h3 id="_3-在飞书开放平台开权限" tabindex="-1">3. 在飞书开放平台开权限 <a class="header-anchor" href="#_3-在飞书开放平台开权限" aria-label="Permalink to &quot;3. 在飞书开放平台开权限&quot;">​</a></h3><ol><li>进入 <strong>应用能力</strong> → <strong>权限管理</strong>。</li><li>至少开启： <ul><li><code>im:message</code>（收发消息）</li><li><code>im:chat</code>（群信息等）</li></ul></li><li>组织有要求时，点 <strong>申请权限</strong> 提交。</li></ol><h3 id="_4-在-memoh-添加飞书渠道-默认-长连接" tabindex="-1">4. 在 Memoh 添加飞书渠道（默认：长连接） <a class="header-anchor" href="#_4-在-memoh-添加飞书渠道-默认-长连接" aria-label="Permalink to &quot;4. 在 Memoh 添加飞书渠道（默认：长连接）&quot;">​</a></h3><ol><li>打开 Bot 的 <strong>平台</strong> 标签页，添加 <strong>飞书</strong> 渠道。</li><li><strong>入站方式</strong> 保持默认的 <code>websocket</code>。</li><li>填 <strong>App ID</strong>、<strong>App Secret</strong>；使用国际版 Lark 时把 <strong>区域</strong> 切到 <code>lark</code>。</li><li>点 <strong>Save</strong>。消息经飞书 <strong>WebSocket 长连接</strong> 送达，无需公网回调地址，也不用配置事件订阅。</li></ol><h3 id="_5-可选-改用-webhook-入站" tabindex="-1">5. 可选：改用 Webhook 入站 <a class="header-anchor" href="#_5-可选-改用-webhook-入站" aria-label="Permalink to &quot;5. 可选：改用 Webhook 入站&quot;">​</a></h3><p>服务端可被公网访问、且更希望走事件回调时，再选这种方式。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>这一步会在 Memoh 和飞书后台之间往返：Memoh 生成回调 URL 后要贴回 <strong>事件订阅</strong> 页，先别关飞书后台。</p></div><ol><li>在 Memoh 把 <strong>入站方式</strong> 改为 <code>webhook</code>；除 <strong>App ID</strong>、<strong>App Secret</strong> 外，再填入与飞书后台事件订阅一致的 <strong>Encrypt Key</strong> 和 <strong>Verification Token</strong>。</li><li>点 <strong>Save</strong>，页面会生成 <strong>Webhook 回调 URL</strong>，复制它。</li><li>回到飞书后台，进入 <strong>应用配置</strong> → <strong>事件订阅</strong>，把 URL 填到 <strong>请求地址</strong> 并保存。</li><li>添加 <strong>接收消息</strong>（<code>im.message.receive_v1</code>）等事件。</li></ol><blockquote><p>官方说明：<a href="https://open.feishu.cn/document/client-docs/bot-v3/add-custom-bot" target="_blank" rel="noreferrer">飞书自定义机器人</a></p></blockquote><h3 id="_6-在飞书开放平台发布应用" tabindex="-1">6. 在飞书开放平台发布应用 <a class="header-anchor" href="#_6-在飞书开放平台发布应用" aria-label="Permalink to &quot;6. 在飞书开放平台发布应用&quot;">​</a></h3><ol><li>进入 <strong>应用发布</strong> → <strong>版本管理与发布</strong>。</li><li>点 <strong>创建版本</strong>，填写信息并提交审批。</li><li>审批通过并发布后，Bot 才能在租户里正常使用。</li></ol><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>App ID</strong></td><td>在飞书开放平台 <strong>凭证与基础信息</strong> 页获取。</td></tr><tr><td><strong>App Secret</strong></td><td>与 App ID 同页获取。</td></tr><tr><td><strong>区域</strong></td><td>使用国际版 Lark 时切到 <code>lark</code>。</td></tr><tr><td><strong>入站方式</strong></td><td><code>websocket</code>（默认，长连接）或 <code>webhook</code>。</td></tr><tr><td><strong>Encrypt Key</strong></td><td>仅 webhook 模式需要，须与飞书后台事件订阅设置一致。</td></tr><tr><td><strong>Verification Token</strong></td><td>仅 webhook 模式需要，须与飞书后台事件订阅设置一致。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>在飞书里私聊 Bot，发送 <code>/help</code>。Bot 回复命令列表即说明渠道已生效。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>飞书支持群聊。把 Bot 加进群后，@它即可在群里对话。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>在 Bot 的 <strong>平台</strong> 标签页可以随时停用或移除该渠道。更换凭据时，更新对应字段（如 <strong>App Secret</strong>）并保存即可。</p><h2 id="faq" tabindex="-1">常见问题 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;常见问题 {#faq}&quot;">​</a></h2><h3 id="app-not-published" tabindex="-1">渠道配好了，Bot 却没反应 <a class="header-anchor" href="#app-not-published" aria-label="Permalink to &quot;渠道配好了，Bot 却没反应 {#app-not-published}&quot;">​</a></h3><p>自建应用要先发布：在飞书开放平台 <strong>应用发布</strong> → <strong>版本管理与发布</strong> 里创建版本并提交审批，审批通过并发布后 Bot 才能在租户里正常使用。</p><h3 id="permission-approval" tabindex="-1">权限要走审批 <a class="header-anchor" href="#permission-approval" aria-label="Permalink to &quot;权限要走审批 {#permission-approval}&quot;">​</a></h3><p>部分组织对应用权限有审批流程：在 <strong>应用能力</strong> → <strong>权限管理</strong> 里点 <strong>申请权限</strong> 提交即可。</p>',33)])])}const b=o(n,[["render",s]]);export{p as __pageData,b as default};
